with official (codice, nome, categoria, sottocategoria, fase, obiettivo, descrizione, durata_min, portieri_min, portieri_max, intensita, difficolta, materiale, variante, coaching_points, errori_comuni, attivo, schema_step_1, schema_step_2, schema_step_3, schema_step_4, schema_step_5, schema_step_6) as (values
  ('GK-PRA-001', 'Presa alta frontale in posizione', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Analitico', 'Migliorare tecnica di presa alta, lettura della traiettoria, posizionamento e sicurezza nella presa.', 'Lancio alto frontale del pallone da parte del preparatore. Presa alta sopra la testa con entrambe le mani.', 8, 1, 4, 'Bassa', 1, 'Palloni, coni', 'Variare lato, altezza e velocità del lancio mantenendo la corretta posizione di attesa.', 'Occhi sempre sulla palla; mani a coppa sopra la testa; pollici vicini; gomiti leggermente flessi; atterraggio in equilibrio.', 'Guardare il pallone tardi; mani non a coppa; gomiti larghi; presa instabile.', true, 'Lancio alto frontale del pallone da parte del preparatore.', 'Presa alta sopra la testa con entrambe le mani.', null, null, null, null),
  ('GK-PRA-002', 'Presa alta con elevazione', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Analitico', 'Migliorare elevazione, coordinazione e tecnica di presa alta nel punto più alto.', 'Lancio alto frontale del pallone da parte del preparatore. Elevazione e presa alta sopra la testa.', 10, 1, 4, 'Media', 2, 'Palloni, coni', 'Variare altezza del lancio e gamba di stacco.', 'Attaccare il pallone; spinta decisa; braccia tese verso l''alto; presa sopra la testa; atterraggio equilibrato.', 'Stacco tardivo; presa troppo bassa; braccia piegate; atterraggio rigido.', true, 'Lancio alto frontale del pallone da parte del preparatore.', 'Elevazione e presa alta sopra la testa.', null, null, null, null),
  ('GK-PRA-003', 'Presa alta con passaggio dell''allenatore', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Analitico', 'Migliorare lettura della traiettoria e presa alta su servizio arcuato dell''allenatore.', 'Passaggio/lancio dell''allenatore verso il portiere. Presa alta del portiere sulla traiettoria del pallone.', 10, 1, 4, 'Media', 2, 'Palloni, coni', 'Variare direzione, altezza e punto di partenza del servizio.', 'Posizione pronta; leggere subito il lancio; muovere i piedi prima della presa; mani sicure sul pallone.', 'Piedi fermi; lettura tardiva; presa davanti al viso; perdita di equilibrio.', true, 'Passaggio/lancio dell''allenatore verso il portiere.', 'Presa alta del portiere sulla traiettoria del pallone.', null, null, null, null),
  ('GK-PRA-004', 'Presa alta in salto frontale', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Analitico', 'Migliorare coordinazione e tecnica di presa alta in salto frontale.', 'Lancio frontale del pallone da parte del preparatore. Salto verso l''alto e presa alta del pallone sopra la testa.', 10, 1, 2, 'Media', 2, 'Palloni, coni', 'Variare altezza e velocità del lancio; inserire un passo indietro prima del salto.', 'Occhi sul pallone; spinta decisa con le gambe; braccia distese; presa sopra la testa.', 'Guardare il pallone tardi; saltare con poca spinta; bloccare il pallone davanti al viso o al petto.', true, 'Lancio frontale del pallone da parte del preparatore.', 'Salto verso l''alto e presa alta del pallone sopra la testa.', null, null, null, null),
  ('GK-PRA-005', 'Presa alta in tuffo laterale da lancio del preparatore', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Analitico', 'Migliorare coordinazione nel tuffo laterale e presa alta in sospensione.', 'Lancio del pallone dal preparatore lateralmente. Tuffo laterale e presa alta con entrambe le mani.', 10, 1, 2, 'Alta', 3, 'Palloni, coni', 'Variare distanza e direzione del lancio; inserire un leggero rimbalzo prima del tuffo.', 'Spinta decisa con la gamba opposta; braccia tese; presa sopra la testa; pollici vicini; occhi sulla palla.', 'Spingere con la gamba sbagliata; estensione incompleta; mani morbide o presa davanti al viso.', true, 'Lancio del pallone dal preparatore lateralmente.', 'Tuffo laterale e presa alta con entrambe le mani.', null, null, null, null),
  ('GK-PRA-006', 'Presa alta in tuffo frontale', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Analitico', 'Migliorare reattività, tecnica di presa alta e spinta in elevazione.', 'Lancio frontale del pallone da parte del partner. Tuffo frontale e presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, coni', 'Variare distanza, potenza e direzione del lancio; alternare lanci tesi e lob.', 'Spinta esplosiva; braccia tese; occhi sul pallone; afferrare sopra la testa; atterrare in equilibrio.', 'Spinta insufficiente; lettura tardiva; braccia piegate; atterraggio sbilanciato.', true, 'Lancio frontale del pallone da parte del partner.', 'Tuffo frontale e presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-007', 'Presa alta su palla arretrata', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare tempo di reazione, coordinazione e presa alta su lanci arretrati.', 'Lancio della palla dal preparatore su traiettoria arretrata. Spinta, salto e presa alta della palla sopra la testa.', 8, 1, 2, 'Alta', 3, 'Palloni, coni', 'Variare traiettoria e altezza; alternare lanci tesi e lob.', 'Spinta decisa; braccia tese; presa sopra la testa; pollici vicini; occhi sempre sul pallone.', 'Partire in ritardo; spinta debole; braccia piegate; estensione incompleta.', true, 'Lancio della palla dal preparatore su traiettoria arretrata.', 'Spinta, salto e presa alta della palla sopra la testa.', null, null, null, null),
  ('GK-PRA-008', 'Presa alta in uscita', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare la tempistica dell''uscita alta e la presa sicura del pallone in elevazione.', 'Lancio alto e profondo del partner verso l''area. Uscita in elevazione e presa alta del pallone con entrambe le mani.', 8, 1, 1, 'Alta', 3, 'Palloni, coni', 'Variare profondità e traiettoria del lancio; inserire rimbalzi prima della presa.', 'Uscita decisa e veloce; braccia tese; presa sopra la testa; ginocchio in spinta; atterraggio equilibrato.', 'Uscire in ritardo; braccia piegate; occhi non fissi sul pallone; piedi disallineati in atterraggio.', true, 'Lancio alto e profondo del partner verso l''area.', 'Uscita in elevazione e presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-009', 'Presa alta in uscita con ostacolo', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare l''uscita in elevazione superando un ostacolo e la presa alta del pallone.', 'Lancio alto del pallone da parte del partner oltre l''ostacolo. Uscita in elevazione superando l''ostacolo e presa alta con entrambe le mani.', 10, 1, 1, 'Alta', 3, 'Palloni, coni, paletti o ostacoli', 'Variare altezza e distanza del lancio; inserire più ostacoli; lancio da posizione laterale.', 'Spinta decisa; braccia tese; presa sopra la testa; ginocchio in spinta; atterraggio equilibrato.', 'Uscire in ritardo; non superare l''ostacolo; braccia piegate; elevazione insufficiente; atterraggio sbilanciato.', true, 'Lancio alto del pallone da parte del partner oltre l''ostacolo.', 'Uscita in elevazione superando l''ostacolo e presa alta con entrambe le mani.', null, null, null, null),
  ('GK-PRA-010', 'Presa alta in tuffo laterale', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare copertura laterale in elevazione e presa alta del pallone in tuffo.', 'Lancio alto e laterale del pallone da parte del partner. Tuffo laterale con presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, coni', 'Variare altezza e direzione del lancio; alternare destra e sinistra.', 'Spinta esplosiva della gamba opposta; braccia tese; presa sopra la testa; atterraggio su spalla e fianco; occhi sul pallone.', 'Partire in ritardo; non coprire la distanza; piegare le braccia; guardare via dal pallone; atterrare con braccia tese.', true, 'Lancio alto e laterale del pallone da parte del partner.', 'Tuffo laterale con presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-011', 'Presa alta in tuffo diagonale', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare l''intervento in elevazione con tuffo diagonale e presa alta in situazioni dinamiche.', 'Lancio alto e diagonale del pallone da parte del partner. Tuffo diagonale, estensione completa e presa alta con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, coni', 'Variare direzione e altezza del lancio; alternare lanci tesi e lob.', 'Spinta esplosiva della gamba opposta; braccia tese; corpo allungato sulla traiettoria; presa alta; atterraggio su spalla e fianco.', 'Partire tardi; non coprire la diagonale; piegare le braccia; perdere il pallone; atterrare su mani o gomito.', true, 'Lancio alto e diagonale del pallone da parte del partner.', 'Tuffo diagonale, estensione completa e presa alta con entrambe le mani.', null, null, null, null),
  ('GK-PRA-012', 'Presa alta in tuffo in avanti', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare l''intervento in avanti in elevazione e la presa alta del pallone lontano dal corpo.', 'Lancio alto del pallone da parte del partner. Tuffo in avanti e presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo', 'Variare distanza e altezza; inserire ostacolo basso da superare.', 'Spinta esplosiva; braccia tese; presa sopra la testa; corpo in estensione completa; atterraggio su petto e spalle.', 'Uscire in ritardo; non estendersi; piegare le braccia; portare il pallone verso il corpo; atterrare su gomiti o mani.', true, 'Lancio alto del pallone da parte del partner.', 'Tuffo in avanti e presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-013', 'Presa alta in tuffo indietro', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare la presa alta in tuffo indietro gestendo coordinazione ed estensione del corpo.', 'Lancio alto del pallone da parte del partner. Tuffo indietro e presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo', 'Variare distanza e altezza; inserire ostacolo basso da superare.', 'Spinta esplosiva della gamba opposta; braccia tese; presa sopra la testa; arco del corpo; atterraggio su schiena e spalle.', 'Uscire in ritardo; estensione incompleta; braccia piegate; perdere il pallone dietro la testa; atterrare su gomiti o mani.', true, 'Lancio alto del pallone da parte del partner.', 'Tuffo indietro e presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-014', 'Presa alta in tuffo a gomito', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare la tecnica di presa alta in tuffo con corretta chiusura a gomito, aumentando sicurezza e stabilità.', 'Lancio alto del pallone da parte del partner. Tuffo a gomito e presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo', 'Variare direzione del lancio; aggiungere ostacolo basso; aumentare leggermente la velocità.', 'Spinta esplosiva; braccia tese; chiusura a gomito per bloccare; presa sopra la testa; corpo allungato; atterraggio su fianco o spalla.', 'Uscire in ritardo; non chiudere a gomito; piegare le braccia; lasciare spazio tra mani e pallone; atterrare su mani o gomiti.', true, 'Lancio alto del pallone da parte del partner.', 'Tuffo a gomito e presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-015', 'Presa alta in tuffo a destra', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare l''intervento in elevazione verso destra con presa alta, coordinazione, estensione e sicurezza.', 'Lancio alto del pallone da parte del partner. Tuffo a destra e presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo', 'Variare distanza e altezza; inserire ostacolo basso; aumentare leggermente la velocità.', 'Spinta esplosiva della gamba opposta; braccia tese; presa sopra la testa; corpo allungato; atterraggio su fianco o spalla destra.', 'Uscire in ritardo; non spingere lateralmente; piegare le braccia; occhi non fissi; atterrare su mani o gomito.', true, 'Lancio alto del pallone da parte del partner.', 'Tuffo a destra e presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-016', 'Presa alta in tuffo basso', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Allenare la presa alta del pallone in tuffo verso il basso, migliorando reattività, coordinazione e sicurezza.', 'Lancio alto del pallone da parte del partner. Tuffo basso e presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo', 'Variare distanza e altezza; inserire ostacolo basso; aumentare leggermente la velocità.', 'Spinta esplosiva della gamba opposta; braccia tese; presa sopra la testa; corpo allungato verso il pallone; atterraggio su fianco o spalla.', 'Uscire in ritardo; piegare le braccia; occhi non fissi; atterrare su mani o gomito.', true, 'Lancio alto del pallone da parte del partner.', 'Tuffo basso e presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-017', 'Presa alta in tuffo frontale', 'Tecnica presa alta e rasoterra', 'Presa alta', 'Disturbo', 'Migliorare la presa alta del pallone in tuffo frontale, curando reattività, coordinazione e sicurezza nell''intervento.', 'Lancio alto del pallone da parte del partner. Tuffo frontale, presa alta del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo, sagoma', 'Variare l''altezza e la distanza del lancio. Inserire ostacolo basso da superare prima dell''intervento.', 'Spinta esplosiva in avanti; braccia tese verso il pallone; presa sopra la testa, pollici vicini; corpo allungato in estensione completa; atterraggio su petto e spalle.', 'Uscire in ritardo; non estendersi completamente; piegare le braccia in presa; perdere il pallone sopra la testa; atterrare su mani o gomiti.', true, 'Lancio alto del pallone da parte del partner.', 'Tuffo frontale, presa alta del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-018', 'Presa bassa in tuffo frontale', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Migliorare la tecnica di presa bassa in tuffo frontale, aumentando reattività, coordinazione e sicurezza nell''intervento.', 'Passaggio rasoterra da parte del partner. Tuffo frontale basso, presa del pallone con entrambe le mani.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo, sagoma', 'Variare la distanza e la velocità del passaggio. Inserire ostacolo basso da superare prima dell''intervento.', 'Partenza in posizione pronta; spinta esplosiva in avanti; mani aperte e dita rivolte verso il pallone; presa sicura con entrambe le mani; corpo dietro il pallone; atterraggio su petto e spalle.', 'Uscire in ritardo; piegare le braccia; occhi non fissi sul pallone; mani ravvicinate o rigide; atterrare su gomiti o mani.', true, 'Passaggio rasoterra da parte del partner.', 'Tuffo frontale basso, presa del pallone con entrambe le mani.', null, null, null, null),
  ('GK-PRA-019', 'Deviazione in tuffo frontale', 'Tecnica presa alta e rasoterra', 'Deviazione', 'Disturbo', 'Migliorare la capacità di deviare il pallone in tuffo frontale, aumentando reattività, coordinazione e protezione della porta.', 'Il partner effettua un passaggio rasoterra verso il centro o leggermente decentrato rispetto alla posizione del portiere. Il portiere si tuffa frontalmente e devia il pallone con entrambe le mani, allontanandolo dalla porta.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo, sagoma', 'Variare la traiettoria del passaggio (centrale, destra, sinistra). Cambiare la velocità del lancio. Inserire un ostacolo davanti al portiere.', 'Partenza in posizione pronta; spinta esplosiva verso il pallone; mani aperte; deviazione con entrambe le mani; occhi sempre sul pallone; corpo allungato a copertura della porta; atterraggio su spalla e fianchi.', 'Uscire in ritardo; mani rigide o non aperte; occhi non fissati sul pallone; deviare centralmente; atterrare su gomiti o mani tese.', true, 'Il partner effettua un passaggio rasoterra verso il centro o leggermente decentrato rispetto alla posizione del portiere.', 'Il portiere si tuffa frontalmente e devia il pallone con entrambe le mani, allontanandolo dalla porta.', null, null, null, null),
  ('GK-PRA-020', 'Presa bassa in tuffo laterale', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Migliorare la presa bassa in tuffo laterale, la reattività, la coordinazione e la sicurezza nell’intervento, andando vicino al terreno.', 'Il partner effettua un passaggio rasoterra verso uno dei lati della porta. Il portiere si sposta lateralmente e si tuffa basso, bloccando il pallone con entrambe le mani vicino al terreno.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo, sagoma', 'Lanciare da destra e sinistra. Variare distanza e velocità. Inserire ostacolo basso da superare prima dell’intervento. Passaggio leggermente più lontano dal portiere.', 'Partenza in posizione pronta; spinta esplosiva laterale; corpo allungato e copertura della palla; mani aperte; presa sicura vicino al terreno; atterraggio su fianco e spalla.', 'Uscire in ritardo; piegare il braccio di presa; occhi non fissi; non andare vicino al terreno; atterrare su gomiti o mani tese.', true, 'Il partner effettua un passaggio rasoterra verso uno dei lati della porta.', 'Il portiere si sposta lateralmente e si tuffa basso, bloccando il pallone con entrambe le mani vicino al terreno.', null, null, null, null),
  ('GK-PRA-021', 'Tuffo basso laterale in appoggio', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Migliorare la tecnica del tuffo basso laterale in appoggio, aumentando reattività, capacità di copertura del lato e sicurezza nella presa a terra.', 'Il partner effettua un passaggio rasoterra verso destra o sinistra del portiere. Il portiere effettua un tuffo basso laterale in appoggio, afferra il pallone con entrambe le mani e lo protegge.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo, sagoma', 'Variare il lato del passaggio, la distanza dal portiere e inserire un ostacolo basso da superare prima dell’intervento.', 'Partenza pronta; spinta esplosiva verso il lato; mani aperte; presa bassa sicura; appoggio su fianco e avambraccio; corpo dietro il pallone; atterraggio controllato e protezione della palla.', 'Uscire in ritardo; mani rigide; occhi non fissi; non portare il corpo dietro il pallone; atterrare su gomito o spalla; lasciare rimbalzare il pallone.', true, 'Il partner effettua un passaggio rasoterra verso destra o sinistra del portiere.', 'Il portiere effettua un tuffo basso laterale in appoggio, afferra il pallone con entrambe le mani e lo protegge.', null, null, null, null),
  ('GK-PRA-022', 'Tuffo basso laterale in spinta', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Migliorare la tecnica del tuffo basso laterale in spinta, aumentando reattività, rapidità d’intervento e sicurezza nella presa a terra.', 'Il partner effettua un passaggio rasoterra forte verso il lato del portiere. Il portiere effettua un tuffo basso laterale in spinta, afferra il pallone con entrambe le mani e lo protegge.', 8, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo, sagoma', 'Variare lato, distanza e velocità del passaggio. Inserire un ostacolo basso da superare prima dell’intervento.', 'Partenza pronta; spinta esplosiva verso il lato; mani aperte; presa bassa sicura; spinta laterale con gamba interna; corpo dietro il pallone; atterraggio su fianco e spalla.', 'Uscire in ritardo; mani rigide; occhi non fissi; non spingere lateralmente; atterrare su gomito o mani tese; lasciare rimbalzare il pallone.', true, 'Il partner effettua un passaggio rasoterra forte verso il lato del portiere.', 'Il portiere effettua un tuffo basso laterale in spinta, afferra il pallone con entrambe le mani e lo protegge.', null, null, null, null),
  ('GK-PRA-023', 'Tuffo basso laterale in appoggio con ripartenza', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Migliorare tuffo basso laterale in appoggio, presa sicura e rapidità di ripartenza verso la posizione di guardia.', 'Il partner effettua un passaggio rasoterra verso il lato del portiere. Il portiere effettua un tuffo basso laterale in appoggio, afferra il pallone con entrambe le mani e lo protegge. Il portiere si rialza rapidamente e ritorna in posizione di guardia.', 10, 1, 2, 'Alta', 3, 'Palloni, cono o ostacolo, sagoma', 'Variare lato e distanza del passaggio. Inserire ostacolo basso. Aggiungere uno stimolo visivo o sonoro prima del passaggio.', 'Partenza pronta; spinta esplosiva; mani aperte; presa sicura; appoggio su fianco e avambraccio; corpo dietro la palla; occhi sul pallone; ripartenza immediata verso la guardia.', 'Uscire in ritardo; mani rigide; occhi non fissi; non proteggere il pallone; non ripartire rapidamente; atterrare su gomito o spalla; lasciare rimbalzare il pallone.', true, 'Il partner effettua un passaggio rasoterra verso il lato del portiere.', 'Il portiere effettua un tuffo basso laterale in appoggio, afferra il pallone con entrambe le mani e lo protegge.', 'Il portiere si rialza rapidamente e ritorna in posizione di guardia.', null, null, null),
