  ('GK-PRA-037', 'Tuffo basso frontale con ritorno, ripartenza e gioco combinato', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Migliorare la tecnica del tuffo basso frontale in presa, il rapido recupero, la ripartenza e la capacità di collegare un secondo passaggio con una giocata combinata.', 'Il partner effettua un passaggio rasoterra frontalmente verso il portiere. Il portiere esegue un tuffo basso frontale in appoggio e blocca il pallone con entrambe le mani. Il portiere ritorna rapidamente in piedi e riparte verso la posizione di guardia. Il partner effettua un secondo passaggio rasoterra. Il portiere effettua un passaggio rasoterra verso il partner opposto. Il partner controlla il pallone e conclude rasoterra verso la porta oppure cambia gioco.', 12, 1, 2, 'Alta', 4, 'Palloni, cono o ostacolo, sagoma/manichino, cartoncini colorati o numeri', 'Variare distanza e velocità dei passaggi. Alternare il lato della seconda giocata. Inserire uno stimolo visivo prima del secondo passaggio. Consentire al partner finale di controllare e cambiare gioco oppure concludere rasoterra.', 'Partenza pronta e reattiva; spinta esplosiva in avanti; presa sicura con corpo dietro il pallone; ritorno rapido in piedi; riposizionamento in guardia; qualità del passaggio rasoterra del portiere; lettura della giocata finale; comunicazione costante.', 'Uscire in ritardo; mani rigide; non proteggere il pallone; ritorno lento; perdita dell''orientamento dopo il secondo passaggio; passaggio del portiere impreciso; mancata lettura della giocata finale.', true, 'Il partner effettua un passaggio rasoterra frontalmente verso il portiere.', 'Il portiere esegue un tuffo basso frontale in appoggio e blocca il pallone con entrambe le mani.', 'Il portiere ritorna rapidamente in piedi e riparte verso la posizione di guardia.', 'Il partner effettua un secondo passaggio rasoterra.', 'Il portiere effettua un passaggio rasoterra verso il partner opposto.', 'Il partner controlla il pallone e conclude rasoterra verso la porta oppure cambia gioco.'),
  ('GK-PRA-038', 'Tuffo basso laterale con spinta + ritorno', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Migliorare la tecnica del tuffo basso laterale in presa, la spinta della gamba opposta, la rapidità di recupero e il ritorno in posizione di guardia per un nuovo intervento.', 'Il partner effettua un passaggio rasoterra lateralmente verso il portiere. Il portiere effettua un tuffo basso laterale, spingendo con la gamba opposta e prende il pallone. Recupera subito il pallone e si porta in posizione eretta su un ginocchio. Ritorna rapidamente in piedi e assume la posizione di guardia. Il partner effettua un passaggio rasoterra dal lato opposto e il portiere ripete il lavoro.', 10, 1, 2, 'Alta', 4, 'Palloni, coni o ostacoli opzionali', 'Variare distanza e velocità dei passaggi. Lavorare su un solo lato o alternare i lati. Inserire ostacoli bassi prima del passaggio. Utilizzare stimoli visivi diversi.', 'Partenza pronta e reattiva; spinta esplosiva della gamba opposta; mano esterna a protezione e presa con entrambe le mani; corpo dietro il pallone; recupero immediato vicino al petto; ritorno rapido in piedi; equilibrio centrale; reazione immediata al nuovo passaggio.', 'Spinta insufficiente o tardiva; mani lente o mal posizionate; corpo davanti al pallone; recupero instabile; ritorno lento o con passi incrociati; disattenzione sul nuovo passaggio.', true, 'Il partner effettua un passaggio rasoterra lateralmente verso il portiere.', 'Il portiere effettua un tuffo basso laterale, spingendo con la gamba opposta e prende il pallone.', 'Recupera subito il pallone e si porta in posizione eretta su un ginocchio.', 'Ritorna rapidamente in piedi e assume la posizione di guardia.', 'Il partner effettua un passaggio rasoterra dal lato opposto e il portiere ripete il lavoro.', null),
  ('GK-PRA-039', 'Tuffo basso in avanti + spinta e ritorno', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Sviluppare la capacità di tuffo basso in avanti per la presa, la velocità di reazione e l''esplosività nella risalita in piedi mantenendo alta l''intensità.', 'Il partner effettua un passaggio rasoterra frontalmente. Il portiere esegue un tuffo basso in avanti e prende il pallone a terra. Spinge con le mani in modo esplosivo e torna rapidamente in piedi. Il portiere rientra in posizione di guardia e si prepara al passaggio successivo. Il partner effettua un secondo passaggio rasoterra.', 10, 1, 2, 'Alta', 4, 'Palloni, coni o ostacoli opzionali', 'Aumentare la distanza del passaggio. Inserire uno o due ostacoli prima del tuffo. Partire già in posizione di ginocchio. Utilizzare stimoli visivi diversi.', 'Partenza pronta e reattiva; tuffo in avanti con presa sicura; mani aperte verso il pallone; corpo dietro il pallone; spinta esplosiva con le mani e appoggio deciso dei piedi; ritorno rapido con passi brevi; equilibrio centrale; reazione immediata al passaggio successivo.', 'Ritardo nella partenza; tuffo corto o presa incompleta; mani troppo vicine; spinta debole con le mani; risalita lenta o con passi incrociati; corpo non dietro il pallone; perdita di equilibrio.', true, 'Il partner effettua un passaggio rasoterra frontalmente.', 'Il portiere esegue un tuffo basso in avanti e prende il pallone a terra.', 'Spinge con le mani in modo esplosivo e torna rapidamente in piedi.', 'Il portiere rientra in posizione di guardia e si prepara al passaggio successivo.', 'Il partner effettua un secondo passaggio rasoterra.', null),
  ('GK-PRA-040', 'Combinazione bassa + alta con due partner', 'Tecnica presa alta e rasoterra', 'Presa rasoterra', 'Disturbo', 'Sviluppare la capacità di gestire in rapida successione una presa bassa e una presa alta, migliorando reattività, transizione e sicurezza negli interventi e nei recuperi.', 'Il primo partner effettua un passaggio rasoterra al portiere. Il portiere esegue un tuffo basso e blocca il pallone a terra. Si rialza rapidamente e si posiziona al centro della porta. Il secondo partner effettua un passaggio alto al portiere. Il portiere salta, prende il pallone in elevazione e ritorna in posizione di guardia.', 12, 1, 2, 'Alta', 4, 'Palloni, coni o ostacoli opzionali', 'Invertire l''ordine: prima alta poi bassa. Aumentare la distanza dei passaggi. Inserire un ostacolo tra i due passaggi. Utilizzare stimoli visivi differenti.', 'Partenza pronta e reattiva; tuffo basso con presa sicura; recupero esplosivo in piedi; posizionamento rapido per la seconda giocata; salto verticale e presa alta sicura; atterraggio stabile; ritorno in posizione di guardia; massima concentrazione.', 'Ritardo sulla prima o seconda giocata; tuffo basso indeciso; recupero lento o non equilibrato; salto senza spinta efficace; mani non corrette nella presa alta; atterraggio instabile o ritorno con passi incrociati.', true, 'Il primo partner effettua un passaggio rasoterra al portiere.', 'Il portiere esegue un tuffo basso e blocca il pallone a terra.', 'Si rialza rapidamente e si posiziona al centro della porta.', 'Il secondo partner effettua un passaggio alto al portiere.', 'Il portiere salta, prende il pallone in elevazione e ritorna in posizione di guardia.', null)
)
insert into public.exercises (
  codice, nome, category_id, subcategory_id, categoria, sottocategoria, fase,
  obiettivo, descrizione, durata_min, portieri_min, portieri_max, intensita,
  difficolta, materiale, variante, coaching_points, errori_comuni, attivo,
  schema_step_1, schema_step_2, schema_step_3, schema_step_4, schema_step_5, schema_step_6
)
select
  o.codice, o.nome, 1, s.id, o.categoria, o.sottocategoria, o.fase,
  o.obiettivo, o.descrizione, o.durata_min, o.portieri_min, o.portieri_max, o.intensita,
  o.difficolta, o.materiale, o.variante, o.coaching_points, o.errori_comuni, o.attivo,
  o.schema_step_1, o.schema_step_2, o.schema_step_3, o.schema_step_4, o.schema_step_5, o.schema_step_6
from official o
join public.exercise_subcategories s
  on s.category_id = 1
 and s.nome = o.sottocategoria
 and s.fase = o.fase
on conflict (codice) do update set
  nome = excluded.nome,
  category_id = excluded.category_id,
  subcategory_id = excluded.subcategory_id,
  categoria = excluded.categoria,
  sottocategoria = excluded.sottocategoria,
  fase = excluded.fase,
  obiettivo = excluded.obiettivo,
  descrizione = excluded.descrizione,
  durata_min = excluded.durata_min,
  portieri_min = excluded.portieri_min,
  portieri_max = excluded.portieri_max,
  intensita = excluded.intensita,
  difficolta = excluded.difficolta,
  materiale = excluded.materiale,
  variante = excluded.variante,
  coaching_points = excluded.coaching_points,
  errori_comuni = excluded.errori_comuni,
  attivo = excluded.attivo,
  schema_step_1 = excluded.schema_step_1,
  schema_step_2 = excluded.schema_step_2,
  schema_step_3 = excluded.schema_step_3,
  schema_step_4 = excluded.schema_step_4,
  schema_step_5 = excluded.schema_step_5,
  schema_step_6 = excluded.schema_step_6;

commit;
